Sum = 0
Count = 0
for each row X in Scores {
    Sum = Sum + X.Mathematics
    Count = Count + 1
}
if (Count == 0) { report "No average"; stop }
Average = Sum / Count
for each row X in Scores {
    if (X.Mathematics < Average) { record X.CardNo }
}

Minimum = 101
Maximum = -1
for each row X in Scores {
    if (X.Mathematics < Minimum) { Minimum = X.Mathematics }
    if (X.Mathematics > Maximum) { Maximum = X.Mathematics }
}

for each row X in Scores {
    if (X.Mathematics >= 84) { Grade = "A" }
    else if (X.Mathematics >= 70) { Grade = "B" }
    else if (X.Mathematics >= 56) { Grade = "C" }
    else { Grade = "D" }
    record (X.CardNo, Grade)
}

Procedure TopThreeMarks(Rows, Field)
    First = -1; Second = -1; Third = -1
    for each row X in Rows {
        v = X[Field]
        if (v > First) {
            Third = Second
            Second = First
            First = v
        } else if (First > v and v > Second) {
            Third = Second
            Second = v
        } else if (Second > v and v > Third) {
            Third = v
        }
    }
    if (Third == -1) { report "Fewer than 3 distinct values" }
    else { return Third }
End Procedure

Procedure SumMarks(Rows, GenderValue, Field)
    Sum = 0
    for each row X in Rows {
        if (X.Gender == GenderValue) {
            Sum = Sum + X[Field]
        }
    }
    return Sum
End Procedure
GirlsMaths = SumMarks(Scores, "F", "Mathematics")
BoysMaths = SumMarks(Scores, "M", "Mathematics")

Procedure MaxMarks(Rows, Field)
    if (Rows is empty) { report "No maximum"; stop }
    Best = first row[Field]
    for each remaining row X in Rows {
        if (X[Field] > Best) { Best = X[Field] }
    }
    return Best
End Procedure

Procedure SubjectTopper(X, Maths3, Physics3, Chemistry3)
    return (X.Mathematics >= Maths3 or
            X.Physics >= Physics3 or
            X.Chemistry >= Chemistry3)
End Procedure

Maths3 = TopThreeMarks(Scores, "Mathematics")
Physics3 = TopThreeMarks(Scores, "Physics")
Chemistry3 = TopThreeMarks(Scores, "Chemistry")
for each row X in Scores {
    if (SubjectTopper(X, Maths3, Physics3, Chemistry3)) {
        Insert X.Total and X.CardNo together into the best 3 slots
    }
}

if (X.Total > FirstTotal) {
    ThirdTotal = SecondTotal; ThirdID = SecondID
    SecondTotal = FirstTotal; SecondID = FirstID
    FirstTotal = X.Total; FirstID = X.CardNo
}

FirstTotal = -1; SecondTotal = -1; ThirdTotal = -1
FirstID = -1; SecondID = -1; ThirdID = -1
for each row X in Scores {
    if (SubjectTopper(X, Maths3, Physics3, Chemistry3)) {
        v = X.Total
        if (v > FirstTotal) {
            ThirdTotal = SecondTotal; ThirdID = SecondID
            SecondTotal = FirstTotal; SecondID = FirstID
            FirstTotal = v; FirstID = X.CardNo
        } else if (FirstTotal > v and v > SecondTotal) {
            ThirdTotal = SecondTotal; ThirdID = SecondID
            SecondTotal = v; SecondID = X.CardNo
        } else if (SecondTotal > v and v > ThirdTotal) {
            ThirdTotal = v; ThirdID = X.CardNo
        } else {
            Record any equality with a retained score for tie review
        }
    }
}
Check the selected IDs, representation rule and any boundary ties
before declaring the final prize winners.

LongNoun = 0; ShortNoun = 0
for each row X in Words {
    if (X.PartOfSpeech == "Noun") {
        if (X.LetterCount > 7) { LongNoun = LongNoun + 1 }
        else { ShortNoun = ShortNoun + 1 }
    }
}

Procedure AddIfBigBazaar(X, SumBB, CountBB)
    if (X.Store == "Big Bazaar") {
        SumBB = SumBB + X.BillAmount
        CountBB = CountBB + 1
    }
    return (SumBB, CountBB)
End Procedure

SumBB = 0; CountBB = 0
for each row X in Bills {
    (SumBB, CountBB) = AddIfBigBazaar(X, SumBB, CountBB)
}
if (CountBB > 0) { AverageBB = SumBB / CountBB }
else { report "No matching bills" }
